render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, y = cfg$y), c("x", "y")); chart_open_device(cfg$outputPath, cfg$format); bins <- max(2, min(10, floor(sqrt(nrow(data))))); hb <- hexbin::hexbin(data[[cfg$x]], data[[cfg$y]], xbins = bins); plot(hb, main = cfg$title %||% "六边形密度图", xlab = cfg$x, ylab = cfg$y); grDevices::dev.off(); cfg$outputPath }
